using System;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Threading.Tasks;using System.Windows.Forms;
internal sealed class InputPreview:Control{
 public Bitmap Texture,Wallpaper;public InputPreview(){DoubleBuffered=true;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(Color.FromArgb(19,28,40));if(Wallpaper!=null){double scale=Math.Max(Width/(double)Wallpaper.Width,Height/(double)Wallpaper.Height);float w=(float)(Wallpaper.Width*scale),h=(float)(Wallpaper.Height*scale);g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(Wallpaper,(Width-w)/2,(Height-h)/2,w,h);}if(Texture!=null)InputAppearance.DrawNine(g,Texture,new RectangleF(8,10,Width-16,Height-20));using(var b=new SolidBrush(AppearanceProfiles.Mode==0?Color.FromArgb(30,32,35):Color.White))g.DrawString("在这里输入消息…",Font,b,28,34);}
 protected override void Dispose(bool disposing){if(disposing){if(Texture!=null)Texture.Dispose();if(Wallpaper!=null)Wallpaper.Dispose();}base.Dispose(disposing);}
}
internal sealed class InputDialog:Form{
 string borderColor;readonly NumericUpDown width=new NumericUpDown{Minimum=1,Maximum=3};readonly Button color=new Button();readonly InputPreview preview=new InputPreview();readonly CheckBox enabled=new CheckBox();readonly TrackBar edge=new TrackBar(),radius=new TrackBar();readonly Label status=new Label();readonly Button apply=new Button();bool syncing,busy;
 public InputDialog(){Text="输入区边框";Font=new Font("Microsoft YaHei UI",10);ClientSize=new Size(640,530);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;Controls.Add(new Label{Text="输入区边框",Font=new Font(Font.FontFamily,18,FontStyle.Bold),Location=new Point(22,16),Size=new Size(590,38)});enabled.Text="显示输入区边框";enabled.SetBounds(22,65,580,28);Controls.Add(enabled);preview.SetBounds(22,108,596,145);preview.Font=Font;Controls.Add(preview);string source=AutoBackground.SavedImage();if(source!=null)using(var image=Image.FromFile(BackgroundEffects.Prepare(source)))preview.Wallpaper=new Bitmap(image);Row("边缘对比",edge,20,100,270);Row("圆角大小",radius,8,20,328);apply.Text="保存并应用";color.Text="边框颜色…";color.SetBounds(22,386,210,30);Controls.Add(color);color.Click+=delegate{using(var d=new StudioColorPicker{FullOpen=true,Color=ColorTranslator.FromHtml(borderColor)})if(d.ShowDialog(this)==DialogResult.OK){borderColor=String.Format("#{0:X2}{1:X2}{2:X2}",d.Color.R,d.Color.G,d.Color.B);color.BackColor=d.Color;RefreshPreview();}};Controls.Add(new Label{Text="线宽",Location=new Point(275,390),Size=new Size(60,24)});width.SetBounds(340,386,70,30);Controls.Add(width);width.ValueChanged+=delegate{RefreshPreview();};apply.SetBounds(22,447,280,36);Controls.Add(apply);apply.Click+=async delegate{await Apply(false);};var off=new Button{Text="关闭输入区边框",Location=new Point(326,447),Size=new Size(292,36)};Controls.Add(off);off.Click+=async delegate{await Apply(true);};status.SetBounds(22,494,596,26);Controls.Add(status);enabled.CheckedChanged+=delegate{RefreshPreview();};var s=InputAppearance.Load();syncing=true;enabled.Checked=s.Enabled;edge.Value=s.Edge;radius.Value=s.Radius;borderColor=s.BorderColor;width.Value=s.LineWidth;color.BackColor=ColorTranslator.FromHtml(borderColor);syncing=false;RefreshPreview();FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;status.Text="正在更新输入框，请稍候。";}};}
 void Row(string title,TrackBar slider,int min,int max,int y){Controls.Add(new Label{Text=title,Location=new Point(22,y),Size=new Size(250,24)});var value=new Label{Location=new Point(520,y),Size=new Size(98,24),TextAlign=ContentAlignment.TopRight};Controls.Add(value);slider.Minimum=min;slider.Maximum=max;slider.TickStyle=TickStyle.None;slider.SetBounds(14,y+23,610,32);Controls.Add(slider);slider.ValueChanged+=delegate{value.Text=slider.Value+(slider==radius?" px":"%");RefreshPreview();};}
 InputSettings Current(){return new InputSettings{Enabled=enabled.Checked,Edge=edge.Value,Radius=radius.Value,BorderColor=borderColor,LineWidth=(int)width.Value};}
 void RefreshPreview(){if(syncing)return;var s=Current();var next=s.Enabled?InputAppearance.Texture(s):null;var old=preview.Texture;preview.Texture=next;if(old!=null)old.Dispose();preview.Invalidate();status.Text="预览已更新；不会改变输入、选字和发送操作。";}
 async Task Apply(bool disable){if(busy)return;try{string source=AutoBackground.SavedImage();if(source==null)throw new IOException("请先选择并应用背景。");if(!NativeBackground.WholeEnabled)throw new IOException("输入框边界需要先开启整窗背景。");busy=true;Enabled=false;if(disable)enabled.Checked=false;InputAppearance.Save(Current());for(int attempt=0;;attempt++){bool retry=false;try{await Task.Run(()=>NativeBackground.Apply(source));break;}catch(IOException e){if(attempt>=4||!e.Message.Contains("另一项背景操作"))throw;retry=true;}if(retry)await Task.Delay(600);}status.Text=disable?"输入区边框已关闭。":"输入区边框已保存并应用。";}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}finally{busy=false;Enabled=true;}}
 internal InputSettings Draft(){return Current();}
 internal void SetDraftBorder(string value,int? edgeValue=null){if(edgeValue.HasValue)edge.Value=edgeValue.Value;borderColor=value;color.BackColor=ColorTranslator.FromHtml(value);enabled.Checked=true;RefreshPreview();}
 internal void SaveDraftOnly(){InputAppearance.Save(Current());}
 public bool OperationBusy{get{return busy;}}public Task ApplyWorkspace(){return Apply(false);} public void RenderForTest(string path){StartPosition=FormStartPosition.Manual;Location=new Point(-30000,-30000);ShowInTaskbar=false;enabled.Checked=true;Show();Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(path);}Close();}
}

